    def _get_presign_client(
        cls,
        *,
        endpoint_url: str,
        addressing_style: str,
    ) -> Any:
        cache_key = (
            endpoint_url,
            settings.AWS_PRIVATE_MEDIA_BUCKET_NAME,
            settings.AWS_PRIVATE_MEDIA_REGION_NAME,
            settings.AWS_PRIVATE_MEDIA_ACCESS_KEY_ID or "",
            settings.AWS_PRIVATE_MEDIA_SECRET_ACCESS_KEY or "",
        )
        cached_client = cls._presign_clients.get(cache_key)
        if cached_client is not None:
            return cached_client

        client = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=settings.AWS_PRIVATE_MEDIA_ACCESS_KEY_ID,
            aws_secret_access_key=settings.AWS_PRIVATE_MEDIA_SECRET_ACCESS_KEY,
            region_name=settings.AWS_PRIVATE_MEDIA_REGION_NAME,
            config=Config(
