        parsed = parse_datetime(start_time)
        if parsed is None:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime_timezone.utc)
        return parsed.astimezone(NETWORK_PLAN_TIMEZONE)

